201	\section{The Magic Square game}
202	% Paper label sec:ms kept for cross-reference fidelity.
203	\label{sec:ms}
204	
205	We recall the Magic Square game of Mermin and Peres. It is a simple self-test for two EPR pairs, and it allows one to test that a pair of binary observables \emph{anticommutes}; both properties are used in the Pauli basis test. Here it is presented as a binary constraint satisfaction game. Throughout this section and the next, $\sigma^X$ and $\sigma^Z$ denote the single-qubit Pauli observables, with associated two-outcome projective measurements $\{\sigma^W_b\}_{b \in \F_2}$ for $W \in \{X,Z\}$.
206	
207	\begin{definition}[The Magic Square game]\label{def:ms-game}
208		\uses{def:game, def:graph-distribution}
209		The Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ is the following two-player game. There are $9$ variables $x_1,\ldots,x_9$ taking values in $\F_2$, arranged in a $3 \times 3$ grid: the cell in row $r$ and column $c$ contains the variable $x_{3(r-1)+c}$. There are $6$ linear equations over these variables: for each of the three rows and each of the first two columns, the sum of the three variables in it equals $0$; for the third column, the sum of the three variables in it equals $1$.
210	
211		The question types are
212		\begin{align*}
213			\mathcal T^{\mathrm{mc}} &= \{\mathsf{Constraint}_i : i = 1,2,\ldots,6\}\;,\\
214			\mathcal T^{\mathrm{mv}} &= \{\mathsf{Variable}_j : j = 1,2,\ldots,9\}\;,\\
215			\mathcal T^{\mathrm{ms}} &= \mathcal T^{\mathrm{mc}} \cup \mathcal T^{\mathrm{mv}}\;,
216		\end{align*}
217		where $\mathsf{Constraint}_i$ for $i \in \{1,2,3\}$ denotes the constraint of row $i$ (with variables $x_{3(i-1)+1}, x_{3(i-1)+2}, x_{3(i-1)+3}$), $\mathsf{Constraint}_4$ and $\mathsf{Constraint}_5$ denote the constraints of the first two columns, and $\mathsf{Constraint}_6$ denotes the constraint of the third column (with variables $x_{i-3}, x_{i}, x_{i+3}$ for $\mathsf{Constraint}_i$, $i \in \{4,5,6\}$).
218	
219		The question distribution is as follows: the verifier samples $\mathsf{Constraint}_i$ uniformly from $\mathcal T^{\mathrm{mc}}$, then samples $\mathsf{Variable}_j$ uniformly among the three variables appearing in the row or column of $\mathsf{Constraint}_i$; one player, chosen uniformly at random, receives $\mathsf{Constraint}_i$ and the other receives $\mathsf{Variable}_j$. Equivalently, the verifier samples a uniformly random edge of the bipartite \emph{type graph} $G^{\mathrm{ms}}$ on vertex sets $\mathcal T^{\mathrm{mc}}$ and $\mathcal T^{\mathrm{mv}}$, whose edges are $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{3(i-1)+j}$ for $i,j \in \{1,2,3\}$ and $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{(i-3)+3(j-1)}$ for $i \in \{4,5,6\}$, $j \in \{1,2,3\}$ ($18$ edges in total, and no self-loops), and sends one endpoint to a uniformly random player and the other endpoint to the other player.
220	
221		The $\mathsf{Constraint}$ player answers with three bits $(\beta_{v_1}, \beta_{v_2}, \beta_{v_3}) \in \F_2^3$, where $(v_1,v_2,v_3)$ are the indices of the three variables of $\mathsf{Constraint}_i$; the $\mathsf{Variable}$ player answers with a single bit $\gamma \in \F_2$. The players win if and only if the $\mathsf{Constraint}$ player's answer satisfies the equation associated with $\mathsf{Constraint}_i$ and $\gamma = \beta_j$.
222	\end{definition}
223	
224	The following theorem records the self-testing (rigidity) properties of the Magic Square game. It is used in the soundness analysis of the Pauli basis test to enforce anticommutation relations between certain pairs of observables.
225	With zero-based labels, the paper's variables $1$ and $5$ have labels $0$ and
226	$4$, respectively.
227	
228	\begin{theorem}[Rigidity of the Magic Square game]\label{thm:ms-rigidity}
229		\lean{MIPStarRE.QPBT.exists_ms_rigidity}
230		\leanok
231		\uses{def:ms-game, def:tensor-product-value, def:EPR, def:povm-distance}
232		Let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy that succeeds in the Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ with probability $1-\eps$, where $\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$. Then there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot \hilb_{\mathrm B''}$, such that:
233		\begin{enumerate}
234			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\sqrt\eps)$;
235			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$,
236			\begin{align*}
237				\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
238				\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
239				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
240				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
241			\end{align*}
242			where each $\approx_{\sqrt\eps}$ holds with respect to the state $\ket{\mathrm{EPR}_2}^{\ot 2}_{\mathrm{A'B'}} \ot \ket{\mathrm{aux}}_{\mathrm{A''B''}}$ and the answer summation is over $b \in \{0,1\}$, and the approximation bounds carry implicit universal constants.
243		\end{enumerate}
244		As a consequence, letting $\tilde A^{\mathsf{Variable}_1} = \tilde A^{\mathsf{Variable}_1}_0 - \tilde A^{\mathsf{Variable}_1}_1$ and $\tilde A^{\mathsf{Variable}_5} = \tilde A^{\mathsf{Variable}_5}_0 - \tilde A^{\mathsf{Variable}_5}_1$ denote the associated observables, it holds that
245		\begin{align*}
246			\tilde A^{\mathsf{Variable}_1} \tilde A^{\mathsf{Variable}_5} \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} -\, \tilde A^{\mathsf{Variable}_5} \tilde A^{\mathsf{Variable}_1} \ot I_{\mathrm{B'B''}}\;,\\
247			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1} \tilde B^{\mathsf{Variable}_5} &\approx_{\sqrt\eps} -\, I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5} \tilde B^{\mathsf{Variable}_1}\;,
248		\end{align*}
249		where, for operators $M$, $N$ that are not POVM elements, the notation $M \approx_\delta N$ means $\bra{\psi} (M-N)^\dagger (M-N) \ket{\psi} \le O(\delta)$ with respect to the same state.
250	\end{theorem}
251	\begin{proof}
252		This result is imported from Theorem~6.9 of~\cite{Coladangelo2017Robust}. There are two minor differences between their statement and the one given here. First, they state a robustness of $O(\eps)$, but measure the closeness of the actual and ideal states in trace norm; expressed as the Euclidean distance between $\phi_{\mathrm A} \ot \phi_{\mathrm B}\ket{\psi}$ and $\ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}}$, this becomes $O(\sqrt\eps)$. Second, their ideal observables for the $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ questions are $I \ot \sigma^Z$ and $\sigma^Z\sigma^X \ot \sigma^Z\sigma^X$; under a local change of basis these are equivalent to $\sigma^X \ot I$ and $\sigma^Z \ot I$, respectively.
253	\end{proof}
254	
255	The converse construction shows that any pair of anticommuting binary observables yields a perfect strategy for the Magic Square game.
256	
257	\begin{theorem}\label{thm:ms-from-ac}
258		\lean{MIPStarRE.QPBT.obsOf, MIPStarRE.QPBT.exists_ms_perfect_strategy_of_anticommuting}
259		\leanok
260		\uses{def:ms-game, def:consistent-measurement, def:spcc, def:EPR, def:tensor-product-value}
261		Let $A = \{A_b\}_{b \in \F_2}$ and $B = \{B_b\}_{b \in \F_2}$ be two-outcome projective measurements acting on $(\C^q)^{\ot n}$ that are consistent on $\ket{\mathrm{EPR}_q}^{\ot n}$ (Definition~\ref{def:consistent-measurement}), and let $\mathcal O_A = A_0 - A_1$ and $\mathcal O_B = B_0 - B_1$ be the corresponding $\pm 1$-valued observables. Suppose that $\mathcal O_A \mathcal O_B = - \mathcal O_B \mathcal O_A$. Then there exists a symmetric strategy $\mathcal S = (\psi, M)$ for the Magic Square game with the following properties:
262		\begin{enumerate}
263			\item $\mathcal S$ is an SPCC (symmetric, projective, consistent, commuting) strategy of value $1$;
264			\item the state is $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$;
265			\item for $b \in \{0,1\}$, $M^{\mathsf{Variable}_1}_b = A_b \ot I$ and $M^{\mathsf{Variable}_5}_b = B_b \ot I$.
266		\end{enumerate}
267	\end{theorem}
268	\begin{proof}
269		\uses{def:consistent-measurement}
270		The strategy is based on the canonical two-qubit operator solution of the Magic Square, with the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$ and the cells of the grid assigned the $\pm 1$-valued observables
271		\[
272			\begin{array}{ccc}
273				\mathcal O_A \ot I & I \ot \sigma^X & \mathcal O_A \ot \sigma^X \\[2pt]
274				I \ot \sigma^Z & \mathcal O_B \ot I & \mathcal O_B \ot \sigma^Z \\[2pt]
275				\mathcal O_A \ot \sigma^Z & \mathcal O_B \ot \sigma^X & \mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X
276			\end{array}
277		\]
278		on $(\C^q)^{\ot n} \ot \C^2$: on question $\mathsf{Variable}_j$ a player measures the two-outcome projective measurement of the observable in cell $j$, and on question $\mathsf{Constraint}_i$ a player simultaneously performs the three measurements of the corresponding row or column; item~3 holds by construction. Anticommutation of $\mathcal O_A$ and $\mathcal O_B$ gives
279		\begin{equation}\label{eq:am-i-hermitian}
280			\mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X
 60		by a base point $u_0$ and a direction $v$ --- for the lines arising as
 61		question contents, the pair read off the line's description, whose base
 62		point is the canonical representative of
 63		Definition~\ref{def:line-representative} --- and an integer $c \geq 0$,
 64		we write $\deg_c(\ell)$ for the set of univariate polynomials of degree
 65		at most $c$, each given by its list of $c+1$ coefficients and identified
 66		by its polynomial representative rather than by the function it induces,
 67		as in Definition~\ref{def:polyfunc}; the argument $\ell$ records the
 68		line to which such an answer refers, through the parameterization
 69		$t \mapsto u_0 + tv$. The cases used below are $\deg_d(\ell)$ and
 70		$\deg_{md}(\ell)$; whenever $d \leq md$, extending coefficient lists by
 71		zeros gives the inclusion $\deg_d(\ell) \subseteq \deg_{md}(\ell)$. For
 72		$f \in \deg_c(\ell)$, $u \in \ell$, and $a \in \F_q$, we say that $f$
 73		\emph{evaluates to $a$ at $u$}, written $f(u) = a$, if $f(t) = a$ for
 74		every $t \in \F_q$ with $u = u_0 + tv$. When $v \neq 0$ this $t$ is
 75		unique, so every $f$ evaluates at every point of $\ell$; when $v = 0$,
 76		so that $\ell = \{u_0\}$, exactly those $f$ that induce a constant
 77		function on $\F_q$ evaluate at $u_0$, to their constant value. An
 78		operator indexed by $f(u)$ is understood to be the zero operator when
 79		$f$ does not evaluate at $u$, and for a family $\{N_f\}$ indexed by
 80		$f \in \deg_c(\ell)$ we write
 81		$N_{[\mathrm{eval}_u(\cdot)=a]} = \sum_{f \colon f(u) = a} N_f$; when
 82		$v = 0$ the classes indexed by $a \in \F_q$ form a sub-measurement
 83		rather than a partition of the outcomes. The \emph{completed} family of
 84		evaluation classes is the family indexed by $a \in \F_q \cup \{\bot\}$
 85		obtained by adjoining the additional class
 86		$N_{[\mathrm{eval}_u(\cdot)=\bot]} = \sum_{f} N_f$, the sum over those
 87		$f$ that do not evaluate at $u$; when $\{N_f\}$ is a POVM,
 88		respectively a projective measurement, the completed classes form one
 89		as well, and when $v \neq 0$ the class
 90		$N_{[\mathrm{eval}_u(\cdot)=\bot]}$ is the zero operator.
 91	\end{definition}
 92	
 93	\begin{remark}[Line answers as coefficient lists]
 94		\label{rem:deg-line-representatives}
 95		The source refers to the elements of $\deg_{md}(\ell)$ as polynomials
 96		``defined on the line $\ell$'', that is, as functions on the point set
 97		of $\ell$, while its decision procedure expects each line answer as a
 98		list of coefficients. The two readings differ. When $md \geq q$,
 99		distinct coefficient lists induce the same function $\F_q \to \F_q$;
100		and when $\ell$ has direction $v = 0$ --- a case the question
101		distributions produce with positive probability
102		(Remark~\ref{rem:ld-win-zero-direction}) --- the point set of $\ell$ is
103		the singleton $\{u_0\}$, so a function on $\ell$ retains only a single
104		field element of the answer. Definition~\ref{def:ideg-deg-polynomials}
105		therefore adopts the coefficient reading, under which the strategy's
106		line measurements are indexed by exactly the answers of the prescribed
107		form, and its evaluation convention reproduces the universal
108		quantification of the line-versus-point clauses of the win predicates
109		(Definition~\ref{def:ld-win-predicate}).
110	\end{remark}
111	
112	Throughout this chapter $q = 2^k$ with $k$ odd is an admissible field size
113	(Definition~\ref{def:admissible-size}) and $M = 2^m$ is the number of
114	$q$-ary qudits tested for per player, as in
115	Chapters~\ref{chap:qpbt-test} and~\ref{chap:qpbt-extraction}. (The letter
116	$M$ also denotes the measurement operators of the strategy under analysis,
117	as in the tuple $\mathcal{S} = (\ket{\psi}, M)$ below and in the
118	super- and subscripted individual operators such as
119	$M^{(\mathrm{Point},W),u}_a$; the meaning is determined by context, as in
120	the source.) Recall from
121	Chapter~\ref{chap:qpbt-algebra} the low-degree code
122	(see Definition~\ref{def:low-degree-encoding}), which maps each vector
123	$h \in \F_q^{M}$, with
124	coordinates indexed by binary strings of length $m$, to a polynomial
125	$g_h \in \mathrm{ideg}_{d,m}(\F_q)$ such that $g_h(u) = h_u$ for every
126	$u \in \{0,1\}^m$; for $x \in \F_q^m$ the associated vector
127	$\mathrm{ind}_m(x) \in \F_q^{M}$ satisfies
128	$g_h(x) = h \cdot \mathrm{ind}_m(x)$ for all $h$. Recall also the finite
129	field trace $\tr = \tr_{q \to 2} \colon \F_q \to \F_2$
130	(see Definition~\ref{def:subfield-trace}).
131	
132	\begin{definition}[Commuting and anticommuting tuples]
133		\label{def:anticommuting-tuple}
134		\lean{MIPStarRE.QPBT.PauliTuple}
135		\lean{MIPStarRE.QPBT.IsAnticommuting, MIPStarRE.QPBT.IsCommuting}
136		\leanok
137		% The quantity gamma is introduced in the source at eq:gamma-value, inside
138		% the completeness analysis of the Pauli basis test; the definition below
139		% is self-contained and does not depend on that occurrence.
140		\uses{def:low-degree-encoding, def:subfield-trace}
141		For a tuple
142		$\omega = (u_X, u_Z, r_X, r_Z) \in (\F_q^m)^2 \times (\F_q)^2$, let
143		\[
144			\gamma(\omega) \,=\, \tr\big( (r_X \cdot \mathrm{ind}_m(u_X)) \cdot (r_Z \cdot \mathrm{ind}_m(u_Z)) \big)\,,
145		\]
146		where $r_W \cdot \mathrm{ind}_m(u_W)$ is the scalar multiple of the
147		vector $\mathrm{ind}_m(u_W) \in \F_q^{M}$, the middle $\cdot$ is the
148		$\F_q$-inner product of two vectors in $\F_q^{M}$, and
149		$\tr = \tr_{q \to 2}$. The tuple $\omega$ is called \emph{anticommuting}
150		if $\gamma(\omega) \neq 0$, and \emph{commuting} if $\gamma(\omega) = 0$.
151	\end{definition}
152	
153	The sign $(-1)^{\gamma(\omega)}$ is exactly the sign with which the
154	generalized Pauli observables $\tau^X(r_X \cdot \mathrm{ind}_m(u_X))$ and
155	$\tau^Z(r_Z \cdot \mathrm{ind}_m(u_Z))$ commute
156	(see Lemma~\ref{lem:twisted-commutation});
157	this is the source of the terminology.
158	
159	\begin{lemma}[Probability of anticommuting tuples]
160		\label{fact:omega-anticomm-prob}
161		\lean{MIPStarRE.QPBT.anticommProb, MIPStarRE.QPBT.anticommProb_eq}
162		\lean{MIPStarRE.QPBT.commProb, MIPStarRE.QPBT.commProb_ge_half}
163		\lean{MIPStarRE.QPBT.anticommProb_ge_of_m_le_q}
164		\lean{MIPStarRE.QPBT.anticommProb_ge_of_one_le_md}
165		\leanok
166		% The source states this result in a `fact' environment; it is stated here
167		% as a lemma, and the paper label is kept verbatim.
168		% The exact value of the anticommuting probability and the constant lower
169		% bounds under the hypothesis m <= q are additions relative to the source,
170		% which asserts only the two bounds displayed at the end of the statement;
171		% the source states those bounds without the hypothesis m, d >= 1, under
172		% which alone they hold (see the remark following this lemma). The
173		% unconditional constant bounds are what the proof of the lemma labelled
174		% lem:qld-win-implications uses.
175		\uses{def:anticommuting-tuple}
176		A tuple $\omega = (u_X,u_Z,r_X,r_Z)$ sampled uniformly at random from
177		$(\F_q^m)^2 \times (\F_q)^2$ is anticommuting with probability exactly
178		\[
179			\big(1 - q^{-1}\big)^{m+1} \cdot \frac{1}{2}\,,
180		\]
181		and commuting with the complementary probability, which is at least
182		$\frac12$. In particular, if $m \leq q$, then $\omega$ is anticommuting
183		with probability at least $2^{-4}$ and commuting with probability at
184		least $\frac12$. If $m, d \geq 1$, then the probability that $\omega$ is
185		anticommuting is at least
186		\[
187			(1 - q^{-m}) \cdot (1 - q^{-1}) \cdot \Big(1 - \frac{md}{q}\Big) \cdot \frac{1}{2}
188			\,\geq\, \Big(1 - \frac{3md}{q}\Big) \cdot \frac{1}{2}\,,
189		\]
190		and the probability that $\omega$ is commuting is also at least
191		$\big(1 - \frac{3md}{q}\big) \cdot \frac{1}{2}$.
192	\end{lemma}
193	\begin{proof}
194		\uses{def:low-degree-encoding, def:indicator-vector, def:admissible-size, def:binary-representation, lem:downsize_field, lem:one}
195		By the definition of the indicator vector
196		(Definition~\ref{def:indicator-vector}), expanding the product over the
197		coordinates $i \in \{1, \dots, m\}$ into a sum over $y \in \{0,1\}^m$
198		gives
199		\[
200			\mathrm{ind}_m(u_X) \cdot \mathrm{ind}_m(u_Z)
201			\,=\, \sum_{y \in \{0,1\}^m} \mathrm{ind}_{m,y}(u_X)\, \mathrm{ind}_{m,y}(u_Z)
202			\,=\, \prod_{i=1}^{m} \big( u_{X,i}\, u_{Z,i} + (1 - u_{X,i})(1 - u_{Z,i}) \big)\,,
203		\]
204		and since $\F_q$ has characteristic $2$, the $i$-th factor equals
205		$1 + u_{X,i} + u_{Z,i}$. Hence
206		\[
207			\gamma(\omega) \,=\, \tr\Big( (r_X r_Z) \cdot \prod_{i=1}^{m} (1 + u_{X,i} + u_{Z,i}) \Big)\,.
208		\]
209		For any fixed $u_X$, the $m$ factors $1 + u_{X,i} + u_{Z,i}$ are
210		independent and uniformly distributed in $\F_q$ over the choice of
211		$u_Z$, so all of them are nonzero with probability $(1-q^{-1})^m$;
212		independently, $r_X \neq 0$ with probability $1 - q^{-1}$. If $r_X = 0$
213		or some factor vanishes, then $\gamma(\omega) = 0$. Otherwise, over the
214		uniform choice of $r_Z$, the argument of the trace is a uniformly random
215		element of $\F_q$. Since $q = 2^k$ is admissible, the trace of an
216		element of $\F_q$ equals the coordinate sum of its binary
217		representation: writing $\kappa$ for the binary representation with
218		respect to the fixed self-dual normal basis
219		(Definition~\ref{def:binary-representation}), item~2 of
220		Lemma~\ref{lem:downsize_field} gives
270		that the source leaves implicit --- the exact anticommuting
271		probability
272		$(1-q^{-1})^{m+1} \cdot \frac12 = \frac18$ is smaller than the claimed
273		lower bound $\big(1 - \frac{3md}{q}\big) \cdot \frac12 = \frac12$. The
274		proof given above therefore computes the probability exactly, using the
275		characteristic-two product formula for
276		$\mathrm{ind}_m(u_X) \cdot \mathrm{ind}_m(u_Z)$, in place of the
277		source's argument via the Schwartz--Zippel lemma; the exact value also
278		supplies the unconditional constant lower bounds used in the proof of
279		Lemma~\ref{lem:qld-win-implications}.
280	\end{remark}
